export const VITE_REACT_TS_TEMPLATE: TemplateBundle = {
  files: TEMPLATE_FILES,
  devCommand: { cmd: 'npm', args: ['run', 'dev'] },
  buildCommand: { cmd: 'npm', args: ['run', 'build'] },
  packageManager: 'npm',
};

export const isDestinationEmpty = (destinationPath: string): boolean => {
  if (!fs.existsSync(destinationPath)) {
    return true;
  }
  const entries = fs.readdirSync(destinationPath);
  return entries.filter((entry) => entry !== '.rivet').length === 0;
};

export const writeCreateAppTemplate = (destinationPath: string): void => {
  writeTemplateBundle(VITE_REACT_TS_TEMPLATE, destinationPath);
};

export const writeTemplateBundle = (
  bundle: TemplateBundle,
  destinationPath: string,
): void => {
  for (const file of bundle.files) {
    const absolutePath = path.join(destinationPath, file.relativePath);
    fs.mkdirSync(path.dirname(absolutePath), { recursive: true });
    fs.writeFileSync(absolutePath, file.contents, 'utf8');
  }
};
